  FT["PH-H6252"] = {"id":"PH-H6252","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7771_1994.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Dumangas市","en":"An Act Declaring October Thirty-one of Every Year a Special Nonworking Public Holiday in the Municipality of Dumangas, Province of Iloilo, to Commemorate the Birth Anniversary of Colonel Quintin D. Salas","orig":"An Act Declaring October Thirty-one of Every Year a Special Nonworking Public Holiday in the Municipality of Dumangas, Province of Iloilo, to Commemorate the Birth Anniversary of Colonel Quintin D. Salas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7771","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7771_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6252-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"October thirty-one of every year is hereby declared a special nonworking public holiday in the Municipality of Dumangas, Province of Iloilo, to commemorate the birth anniversary of Colonel Quintin D. Salas, a Visayan revolutionary hero of the Philippine-American War who serves as an inspiration to the Filipinos especially the Visayan and youth of the land."}},{"id":"PH-H6252-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p89"};
