  FT["PH-H6257"] = {"id":"PH-H6257","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7776_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立T'boli市","en":"An Act Establishing a National High School in Sitio Lugan, Barangay Poblacion, Municipality of T'boli, Province of South Cotabato, to Be Known as the T'boli National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Sitio Lugan, Barangay Poblacion, Municipality of T'boli, Province of South Cotabato, to Be Known as the T'boli National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7776","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7776_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6257-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in Barangay Poblacion, Municipality of T'boli, Province of South Cotabato, to be known as the T'boli National High School."}},{"id":"PH-H6257-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports (DECS) shall issue and publish the necessary rules and regulations to implement the provisions of this Act."}},{"id":"PH-H6257-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture and Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6257-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p89"};
  FT["PH-H6258"] = {"id":"PH-H6258","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7777_1994.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Pitogo市","en":"An Act Establishing Paulino Dari High School in the Municipality of Pitogo, Province of Zamboanga Del Sur, and Appropriating Funds Therefor","orig":"An Act Establishing Paulino Dari High School in the Municipality of Pitogo, Province of Zamboanga Del Sur, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7777","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7777_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6258-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in the Municipality of Pitogo, Province of Zamboanga del Sur, to be known as the Paulino Dari High School."}},{"id":"PH-H6258-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture and Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6258-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p89"};
  FT["PH-H6259"] = {"id":"PH-H6259","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1994/ra_7778_1994.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Dumaran市","en":"An Act Establishing a National High School in Barangay Itangil, Municipality of Dumaran, Province of Palawan, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Itangil, Municipality of Dumaran, Province of Palawan, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7778","issuingBody":"Congress of the Philippines","promulgatedDate":"1994-06-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1994/ra_7778_1994.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6259-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in Barangay Itangil, Municipality of Dumaran, Province of Palawan, to be known as the Dumaran Mainland National High School."}},{"id":"PH-H6259-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6259-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be funded out of the appropriations authorized by Republic Act No. 7663 for the Department of Education, Culture and Sports intended for the operational expenses of newly legislated high schools. Thereafter, the amount needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6259-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p89"};
